package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector.ebeMultiply
 */
public class OpenMapRealVector_ebeMultiply_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testEbeMultiplyWithSparseVectors() {
        // Setup: v1 = [1.0, 0.0, 3.0, 0.0, 5.0]
        OpenMapRealVector v1 = new OpenMapRealVector(5);
        v1.setEntry(0, 1.0);
        v1.setEntry(2, 3.0);
        v1.setEntry(4, 5.0);

        // Setup: v2 = [2.0, 0.0, 4.0, 0.0, 6.0]
        // Using ArrayRealVector to represent the parameter v
        ArrayRealVector v2 = new ArrayRealVector(new double[]{2.0, 0.0, 4.0, 0.0, 6.0});

        // Execution
        OpenMapRealVector result = v1.ebeMultiply(v2);

        // Verification
        Assert.assertEquals("Dimension mismatch", 5, result.getDimension());
        Assert.assertEquals("Index 0 failed", 2.0, result.getEntry(0), EPSILON);
        Assert.assertEquals("Index 1 failed", 0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals("Index 2 failed", 12.0, result.getEntry(2), EPSILON);
        Assert.assertEquals("Index 3 failed", 0.0, result.getEntry(3), EPSILON);
        Assert.assertEquals("Index 4 failed", 30.0, result.getEntry(4), EPSILON);
    }

    @Test
    public void testEbeMultiplyWithIdentity() {
        OpenMapRealVector v1 = new OpenMapRealVector(new double[]{10.0, 20.0, 30.0});
        ArrayRealVector identity = new ArrayRealVector(new double[]{1.0, 1.0, 1.0});

        OpenMapRealVector result = v1.ebeMultiply(identity);

        Assert.assertEquals(10.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(20.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(30.0, result.getEntry(2), EPSILON);
    }

    @Test
    public void testEbeMultiplyWithZero() {
        OpenMapRealVector v1 = new OpenMapRealVector(new double[]{1.0, 2.0, 3.0});
        ArrayRealVector zeros = new ArrayRealVector(new double[]{0.0, 0.0, 0.0});

        OpenMapRealVector result = v1.ebeMultiply(zeros);

        Assert.assertEquals(0.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(2), EPSILON);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeMultiplyDimensionMismatch() {
        OpenMapRealVector v1 = new OpenMapRealVector(3);
        v1.setEntry(0, 1.0);

        ArrayRealVector v2 = new ArrayRealVector(2); // Different dimension
        v2.setEntry(0, 1.0);

        // This should trigger checkVectorDimensions(v.getDimension())
        v1.ebeMultiply(v2);
    }

    @Test
    public void testEbeMultiplyEmptyVector() {
        OpenMapRealVector v1 = new OpenMapRealVector(0);
        ArrayRealVector v2 = new ArrayRealVector(0);

        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(0, result.getDimension());
    }

    @Test
    public void testEbeMultiplyResultIsNewObject() {
        OpenMapRealVector v1 = new OpenMapRealVector(new double[]{1.0, 2.0});
        ArrayRealVector v2 = new ArrayRealVector(new double[]{3.0, 4.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        // Ensure it's not the same instance
        Assert.assertNotSame(v1, result);
        // Ensure original v1 is not modified
        Assert.assertEquals(1.0, v1.getEntry(0), EPSILON);
    }
}
